import com.example.payment.application.refund.RefundGateway;
import com.example.payment.domain.refund.RefundOutcome;
import com.example.payment.domain.shared.Money;
import java.math.BigDecimal;
import org.springframework.http.MediaType;
import org.springframework.web.client.RestClient;

/** Talks to the provider's REST API: POST /refunds answers 200 when refunded and 409 when it cannot be. */
public final class HttpRefundGateway implements RefundGateway {

    private final RestClient client;

    public HttpRefundGateway(RestClient client) {
        this.client = client;
    }

    @Override
    public RefundOutcome refund(String reference, Money amount) {
        var request = new RefundRequest(reference, amount.amount(), amount.currency());
        return client.post()
                .uri("/refunds")
                .contentType(MediaType.APPLICATION_JSON)
                .body(request)
                .exchange((sent, response) -> {
                    if (response.getStatusCode().value() == 409) return RefundOutcome.REJECTED;
                    if (response.getStatusCode().isError()) {
                        throw new IllegalStateException("Payment provider answered " + response.getStatusCode());
                    }
                    return RefundOutcome.REFUNDED;
                });
    }

    record RefundRequest(String reference, BigDecimal amount, String currency) {}
}
